const { chromium } = require('playwright');
const base='http://127.0.0.1:8787';
const gif='data:image/gif;base64,R0lGODlhAQABAIAAAAAAAP///ywAAAAAAQABAAACAUwAOw==';
const assert=(v,m)=>{if(!v)throw new Error(m);};
const mark=m=>console.log(`VISIBLE CHECKPOINT: ${m}`);
async function api(r,method,path,data){const res=await r.fetch(`${base}${path}`,{method,headers:data===undefined?undefined:{'Content-Type':'application/json'},data});const p=await res.json().catch(()=>({}));if(res.status()<200||res.status()>=300)throw new Error(`${method} ${path} ${res.status()}: ${p.message||JSON.stringify(p)}`);return p;}
function opts(p){return{relationships:p.relationshipOptions||p.relationships||p.options?.relationships||[],intentions:p.intentionOptions||p.intentions||p.options?.intentions||[]};}
async function user(browser,suffix,selection=null,owner=false){const context=await browser.newContext({viewport:{width:1440,height:900}}),username=`visible_${suffix}`,password=`Visible-${suffix}-2026!`;const s=await context.request.post(`${base}/api/auth/signup`,{data:{username,displayName:`Visible ${suffix}`,email:`${username}@example.test`,password,rememberMe:false}});assert(s.status()===201,`signup ${suffix}`);const o=opts(await api(context.request,'GET','/api/onboarding')),relationshipId=selection?.relationshipId||o.relationships[0].id,intentionIds=selection?.intentionIds||o.intentions.slice(0,2).map(x=>x.id);await api(context.request,'POST','/api/onboarding/relationship',{relationshipId});await api(context.request,'POST','/api/onboarding/intentions',{intentionIds});if(owner)await api(context.request,'POST','/api/bootstrap/owner',{password});const session=await api(context.request,'GET','/api/auth/session');return{context,id:session.user.id,username,selection:{relationshipId,intentionIds}};}
(async()=>{const browser=await chromium.launch({headless:true});let owner,visitor;const errors=[];try{owner=await user(browser,'owner',null,true);visitor=await user(browser,'visitor',owner.selection,false);const op=await api(owner.context.request,'GET','/api/experience/dashboard/pages'),vp=await api(visitor.context.request,'GET','/api/experience/dashboard/pages'),group=op.groups.find(g=>vp.groups.some(v=>v.id===g.id));assert(group,'shared group');await api(owner.context.request,'POST','/api/platform/items',{type:'project',title:'Visible project',body:'Functional profile project',visibility:'account',data:{status:'active',progress:90}});await api(owner.context.request,'POST','/api/platform/items',{type:'media',title:'Visible media',body:'Functional media',visibility:'account',data:{mediaUrl:gif,alt:'Visible GIF',category:'test'}});const pages=await api(owner.context.request,'POST','/api/experience/dashboard/pages',{name:'Visible shared dashboard',scope:'group',groupId:group.id,layout:{tiles:[{featureId:'feature-chat-groups',x:0,y:0,width:3,height:2}],preferences:{density:'comfortable',tileGap:12,outerMargin:0,showDescriptions:true}}}),page=pages.pages.find(p=>p.name==='Visible shared dashboard');await api(owner.context.request,'PUT',`/api/dashboard/collaborators/${page.id}`,{collaborators:[{userId:visitor.id,permission:'manage'}]});await api(owner.context.request,'POST','/api/chat/rooms/chat-global/messages',{type:'text',body:'Visible global chat'});const direct=await api(owner.context.request,'POST','/api/chat/direct',{userId:visitor.id});await api(owner.context.request,'POST',`/api/chat/rooms/${direct.roomId}/messages`,{type:'gif',body:'Visible GIF',mediaUrl:gif});const xp=await api(owner.context.request,'GET',`/api/progression/${owner.id}`);assert(xp.profile.totalXp>=50&&xp.earned.length,'progression');mark('data, collaboration, chat and XP ready');
const dash=await owner.context.newPage();dash.on('pageerror',e=>errors.push(`dashboard:${e.message}`));await dash.goto(`${base}/dashboard`,{waitUntil:'networkidle'});assert(await dash.locator('#grev-chat-panel').count()===1,'duplicate chat panel');assert(await dash.locator('#global-notification-button').count()===1,'notification button');assert(await dash.locator('#global-notification-link').count()===0,'old notification link still present');await dash.locator('#customize-dashboard').click({noWaitAfter:true});await dash.locator('#dashboard-advanced-tools').waitFor({state:'visible'});assert(await dash.locator('#dashboard-multi-select').count()===1,'advanced tools');await dash.locator('#dashboard-cancel-layout').click();await dash.locator(`.dashboard-page-tab[data-page-id="${page.id}"]`).click();await dash.locator('#customize-dashboard').click({noWaitAfter:true});await dash.locator('#dashboard-collaborators').click();await dash.locator('#dashboard-collaboration-dialog').waitFor({state:'visible'});assert(await dash.locator(`#dashboard-collaborator-list [data-user-id="${visitor.id}"]`).count()===1,'collaborator UI');await dash.locator('[data-collaboration-close]').first().click();await dash.locator('#dashboard-cancel-layout').click();await dash.locator('#grev-chat-launcher').click();await dash.locator('#grev-chat-panel').waitFor({state:'visible'});await dash.locator('.grev-chat-room[data-room-id="chat-global"]').click();await dash.getByText('Visible global chat',{exact:true}).waitFor({state:'visible'});await dash.locator('[data-chat-minimise]').click();await dash.locator('#grev-chat-dock').waitFor({state:'visible'});await dash.locator('#grev-chat-dock').click();await dash.locator('#grev-chat-panel').waitFor({state:'visible'});mark('dashboard editor, collaboration and chat dock');
const hub=await owner.context.newPage();hub.on('pageerror',e=>errors.push(`hub:${e.message}`));await hub.goto(`${base}/hub`,{waitUntil:'networkidle'});await hub.locator('[data-hub-tab="projects"]').click();await hub.getByText('Visible project',{exact:true}).waitFor({state:'visible'});assert(await hub.locator('#grev-chat-panel').count()===1,'hub duplicate chat');mark('content hub UI');
const profile=await owner.context.newPage();profile.on('pageerror',e=>errors.push(`profile:${e.message}`));await profile.goto(`${base}/profile/${owner.id}`,{waitUntil:'networkidle'});await profile.locator('.profile-card-xp .chat-xp').waitFor({state:'visible'});await profile.locator('#profile-achievements').waitFor({state:'visible'});assert(await profile.locator('#profile-achievements .profile-achievement img').count()>=8,'achievement art');assert(await profile.locator('#profile-functional-modules .profile-functional-module').count()>=2,'functional modules');assert(await profile.locator('#grev-chat-panel').count()===1,'profile duplicate chat');const other=await owner.context.newPage();other.on('pageerror',e=>errors.push(`other:${e.message}`));await other.goto(`${base}/profile/${visitor.id}`,{waitUntil:'networkidle'});await other.locator('#profile-card').click();await other.locator('#global-profile-card-popover').waitFor({state:'visible'});await other.locator('.global-profile-card-xp .chat-xp').waitFor({state:'visible'});await other.locator('.global-profile-card-message-button').click();await other.locator('#grev-chat-panel').waitFor({state:'visible'});assert((await other.locator('.grev-chat-person-card').textContent()).includes('Visible visitor'),'direct header card');mark('profile modules, achievement art, XP bars and direct chat');assert(!errors.length,errors.join(' | '));console.log('Visible platform UI verification passed.');}finally{await owner?.context.close();await visitor?.context.close();await browser.close();}})().catch(e=>{console.error(`VISIBLE FAILURE: ${e.stack||e}`);process.exit(1);});
